namespace Ehr.Data.Patients;

// A one-time code that lets a patient register for the portal, handed to them at the clinic: the SHA-256 of the
// code, who issued it, when it stops working, and when it was used. The code itself is never stored, so the hash is
// useless without it. Not under row-level security, because registration looks the code up before anyone is signed
// in, and forced RLS binds even the table owner; it holds no clinical data. Issuing a code is recorded as an audit
// event by the app.
public class PatientEnrollment
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    public Guid PatientId { get; set; }

    // Hex SHA-256 of the code.
    public required string CodeHash { get; set; }

    // The staff account that issued it.
    public Guid? IssuedBy { get; set; }

    public DateTimeOffset IssuedAt { get; set; }

    public DateTimeOffset ExpiresAt { get; set; }

    // Set when a patient registers with the code; a redeemed code never works again.
    public DateTimeOffset? RedeemedAt { get; set; }
}
